{% doc %}
  Fulldev UI form styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-form.css' | asset_url | stylesheet_tag }}

/* Fulldev UI's form. Shopify form tags take a class, so their forms use .form. */
.form,
[data-slot='form'] {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing) * 6);
}
.form-error {
  font-size: 0.875rem;
  color: var(--destructive);
}
.form-error:empty {
  display: none;
}
